import{_ as t,o,c as r,a4 as a}from"./chunks/framework.DzJZdBQK.js";const p=JSON.parse('{"title":"ZeroNet安装","description":"","frontmatter":{"date":"2017-10-26T08:23:47","title":"ZeroNet安装","categories":["zeronet"],"tags":["ZeroNet"]},"headers":[{"level":2,"title":"安装ZeroNet","slug":"安装zeronet","link":"#安装zeronet","children":[]},{"level":2,"title":"Debian Linux手动安装","slug":"debian-linux手动安装","link":"#debian-linux手动安装","children":[]},{"level":2,"title":"Vagrant","slug":"vagrant","link":"#vagrant","children":[]},{"level":2,"title":"Docker","slug":"docker","link":"#docker","children":[]},{"level":2,"title":"Virtualenv","slug":"virtualenv","link":"#virtualenv","children":[]}],"relativePath":"posts/zeronet/zeronet-2.md","filePath":"posts/zeronet/zeronet-2.md"}'),l={name:"posts/zeronet/zeronet-2.md"};function i(n,e,d,c,u,s){return o(),r("div",null,[...e[0]||(e[0]=[a('<h2 id="安装zeronet" tabindex="-1">安装ZeroNet <a class="header-anchor" href="#安装zeronet" aria-label="Permalink to &quot;安装ZeroNet&quot;">​</a></h2><ul><li>下载ZeroNet安装包：<a href="https://github.com/HelloZeroNet/ZeroNet-win/archive/dist/ZeroNet-win.zip" target="_blank" rel="noreferrer">Microsoft Windows</a>,<a href="https://github.com/HelloZeroNet/ZeroNet-mac/archive/dist/ZeroNet-mac.zip" target="_blank" rel="noreferrer">Apple macOS</a>, <a href="https://github.com/HelloZeroNet/ZeroBundle/raw/master/dist/ZeroBundle-linux64.tar.gz" target="_blank" rel="noreferrer">Linux 64bit</a>,<a href="https://github.com/HelloZeroNet/ZeroBundle/raw/master/dist/ZeroBundle-linux32.tar.gz" target="_blank" rel="noreferrer">Linux 32bit</a></li><li>解压</li><li>运行 <code>ZeroNet.exe</code> (win), <code>ZeroNet(.app) </code>(macOS), <code>ZeroNet.sh</code>(linux)</li></ul><h2 id="debian-linux手动安装" tabindex="-1">Debian Linux手动安装 <a class="header-anchor" href="#debian-linux手动安装" aria-label="Permalink to &quot;Debian Linux手动安装&quot;">​</a></h2><ul><li><code>sudo apt-get update</code></li><li><code>sudo apt-get install msgpack-python python-gevent</code></li><li><code>wget https://github.com/HelloZeroNet/ZeroNet/archive/master.tar.gz</code></li><li><code>tar xvpfz master.tar.gz</code></li><li><code>cd ZeroNet-Master</code></li><li>运行<code>python zeronet.py</code></li><li>浏览器中打开<code>http://127.0.0.1:43110</code></li></ul><h2 id="vagrant" tabindex="-1">Vagrant <a class="header-anchor" href="#vagrant" aria-label="Permalink to &quot;Vagrant&quot;">​</a></h2><ul><li><code>vagrant up</code></li><li>访问VM<code>vagrant sh</code></li><li><code>cd /vagrant</code></li><li>运行<code>python zeronet.py --ui_ip 0.0.0.0</code></li><li>浏览器中打开<code>http://127.0.0.1:43110</code></li></ul><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><ul><li><code>docker run -d -v &amp;lt;local_data_folder&amp;gt;:/root/data -p 15441:15441 -p 43110:43110 nofish/zeronet</code></li><li>这个Docker镜像包含了Tor代理，默认是关闭的。注意有些节点不允许在你运行Tor。如果你需要开启，将环境变量<code>ENABLE_TOR</code>设置为<code>true</code>(默认是<code>false</code>)。比如： <code>docker run -d -e &quot;ENABLE_TOR=true&quot; -v &amp;lt;local_data_folder&amp;gt;:/root/data -p 15441:15441 -p 127.0.0.1:43110:43110 nofish/zeronet</code></li><li>浏览器中打开<code>http://127.0.0.1:43110</code></li></ul><h2 id="virtualenv" tabindex="-1">Virtualenv <a class="header-anchor" href="#virtualenv" aria-label="Permalink to &quot;Virtualenv&quot;">​</a></h2><ul><li><code>virtualenv env</code></li><li><code>source env/bin/activate</code></li><li><code>pip install msgpack-python gevent</code></li><li><code>python zeronet.py</code></li><li>浏览器中打开<code>http://127.0.0.1:43110</code></li></ul>',10)])])}const g=t(l,[["render",i]]);export{p as __pageData,g as default};
